import { initCommandPalette } from "../js/command-palette.js?v=276fa973-palette";
import { initSiteHeader } from "../js/site-header.js?v=276fa973-header";
import { initTheme } from "../js/theme.js?v=276fa973";

/* Slide viewer for a talk page (generated by scripts/build-talks.mjs).
   Without this script the slides are a plain list, one under another, each
   with its text in a <details>. With it they become one slide at a time:
   previous/next buttons, a counter, a thumbnail strip, arrow keys, swipe,
   full screen, and /talks/<slug>/#slide-12 links that open on that slide.
   Hidden slides' images are lazy, so only the slides you look at (and the
   ones either side) are fetched. */
function initViewer() {
  const viewer = document.querySelector("[data-talk-viewer]");
  const list = viewer?.querySelector("[data-talk-slides]");
  if (!viewer || !list) return;
  const slides = [...list.querySelectorAll("[data-talk-slide]")];
  const total = slides.length;
  if (!total) return;
  let current = 0;

  const icon = (d) => `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${d}"/></svg>`;
  const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
  const bar = document.createElement("div");
  bar.className = "talk-bar";
  bar.innerHTML =
    `<button type="button" class="talk-btn" data-talk-prev aria-label="Previous slide">${icon("M15 6l-6 6 6 6")}</button>` +
    `<p class="talk-count" aria-live="polite"><span data-talk-n>1</span> / ${total}</p>` +
    `<button type="button" class="talk-btn" data-talk-next aria-label="Next slide">${icon("M9 6l6 6-6 6")}</button>` +
    `<button type="button" class="talk-btn talk-full" data-talk-full aria-label="Full screen" title="Full screen (F)">${icon("M4 9V4h5M20 9V4h-5M4 15v5h5M20 15v5h-5")}</button>`;
  const strip = document.createElement("nav");
  strip.className = "talk-strip";
  strip.setAttribute("aria-label", "All slides");
  strip.innerHTML = slides.map((slide, i) => {
    const img = slide.querySelector("img");
    return `<button type="button" data-talk-go="${i}" aria-label="${esc(img.alt)}"><img src="${esc(img.dataset.thumb)}" alt="" width="160" height="90" loading="lazy" decoding="async" /><span>${i + 1}</span></button>`;
  }).join("");
  viewer.prepend(bar);
  viewer.append(strip);
  viewer.classList.add("is-viewer");

  const thumbs = [...strip.querySelectorAll("[data-talk-go]")];
  const counter = bar.querySelector("[data-talk-n]");
  const prev = bar.querySelector("[data-talk-prev]");
  const next = bar.querySelector("[data-talk-next]");

  /* fetch the slides either side so moving on is instant */
  const warm = (i) => {
    const img = slides[i]?.querySelector("img");
    if (img && !img.dataset.warm) { img.loading = "eager"; img.dataset.warm = "1"; }
  };

  const show = (i, { focusThumb = false, updateHash = true } = {}) => {
    current = Math.max(0, Math.min(total - 1, i));
    slides.forEach((slide, j) => { slide.hidden = j !== current; });
    thumbs.forEach((thumb, j) => {
      if (j === current) thumb.setAttribute("aria-current", "true"); else thumb.removeAttribute("aria-current");
    });
    counter.textContent = String(current + 1);
    prev.disabled = current === 0;
    next.disabled = current === total - 1;
    warm(current); warm(current + 1); warm(current - 1);
    const thumb = thumbs[current];
    thumb.scrollIntoView({ block: "nearest", inline: "nearest" });
    if (focusThumb) thumb.focus();
    if (updateHash) history.replaceState(null, "", `#slide-${current + 1}`);
  };

  const fromHash = () => {
    const match = location.hash.match(/^#slide-(\d+)$/);
    return match ? Number(match[1]) - 1 : 0;
  };

  prev.addEventListener("click", () => show(current - 1));
  next.addEventListener("click", () => show(current + 1));
  strip.addEventListener("click", (event) => {
    const button = event.target.closest("[data-talk-go]");
    if (button) show(Number(button.dataset.talkGo));
  });

  /* full screen on the viewer itself; the button is hidden where unsupported */
  const full = bar.querySelector("[data-talk-full]");
  const toggleFull = () => {
    if (document.fullscreenElement) document.exitFullscreen();
    else viewer.requestFullscreen?.().catch(() => {});
  };
  if (!viewer.requestFullscreen) full.hidden = true;
  full.addEventListener("click", toggleFull);
  document.addEventListener("fullscreenchange", () => {
    const on = document.fullscreenElement === viewer;
    viewer.classList.toggle("is-full", on);
    full.setAttribute("aria-label", on ? "Exit full screen" : "Full screen");
  });

  /* keys work anywhere on the page outside text fields and the palette */
  document.addEventListener("keydown", (event) => {
    if (event.ctrlKey || event.metaKey || event.altKey) return;
    const target = event.target;
    if (target.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(target.tagName) || document.body.classList.contains("command-open")) return;
    const step = { ArrowRight: 1, ArrowLeft: -1, PageDown: 1, PageUp: -1 }[event.key];
    if (step) { event.preventDefault(); show(current + step); return; }
    if (event.key === "Home") { event.preventDefault(); show(0); }
    else if (event.key === "End") { event.preventDefault(); show(total - 1); }
    else if (event.key === "f" || event.key === "F") { event.preventDefault(); toggleFull(); }
  });

  /* horizontal swipe on the slide */
  let startX = null, startY = null;
  list.addEventListener("pointerdown", (event) => {
    if (event.pointerType === "mouse") return;
    startX = event.clientX; startY = event.clientY;
  });
  list.addEventListener("pointerup", (event) => {
    if (startX === null) return;
    const dx = event.clientX - startX, dy = event.clientY - startY;
    startX = null;
    if (Math.abs(dx) > 50 && Math.abs(dx) > Math.abs(dy) * 1.5) show(current + (dx < 0 ? 1 : -1));
  });
  /* a click on the right or left of the slide also moves on or back */
  list.addEventListener("click", (event) => {
    if (!event.target.closest("img")) return;
    const box = event.target.getBoundingClientRect();
    show(current + (event.clientX > box.left + box.width / 3 ? 1 : -1));
  });

  addEventListener("hashchange", () => show(fromHash(), { updateHash: false }));
  show(fromHash(), { updateHash: false });
  if (location.hash.startsWith("#slide-")) viewer.scrollIntoView({ block: "start" });
}

document.addEventListener("DOMContentLoaded", () => {
  initCommandPalette();
  initSiteHeader();
  initTheme();
  initViewer();
});
